use super::*;use dm_tree::frontend::{build,BodyArena};use std::path::Path;
struct Source{acquired:dm_preprocess::AcquiredSource}
impl Source{fn new(text:impl AsRef<[u8]>)->Self{Self{acquired:dm_preprocess::AcquiredSource::from_original_bytes(text.as_ref().to_vec(),())}}}
impl dm_preprocess::SourceProvider for Source{
 fn read(&self,_:&Path)->Result<String,String>{Err("directive source fixture requires original acquired bytes".into())}
 fn acquired_source(&self,_:&Path)->Result<Option<dm_preprocess::AcquiredSource>,String>{Ok(Some(self.acquired.clone()))}
 fn source_acquisition(&self,_:&Path,text:&dm_preprocess::SourceText)->Option<dm_preprocess::AcquiredSource>{self.acquired.lease().source_text().same_view(text).then(||self.acquired.clone())}
}
fn observe(source:&str,family:Family)->Vec<Diagnostic>{let front=build(Path::new("binding.dme"),&Source::new(source),&Default::default(),1).unwrap();let arena=BodyArena::new_typed(&front,|_|true);let mut rows=Vec::new();for occurrence in front.bodies.iter(){rows.extend(arena.with_parsed(occurrence,|body|check(&BodyView::new(&front,body)?,family,if matches!(family,Family::Incompatible){Severity::Error}else{Severity::Warning})).unwrap().unwrap());}rows}
#[test]fn directive_binding_rejects_global_before_disabled_and_never_inserts_rejected_flags(){let source="/proc/probe()\n    set SpacemanDMM_should_not_override = 0\n    set SpacemanDMM_should_not_override = 1\n    set SpacemanDMM_should_not_override = 1\n    return 0\n";let rows=observe(source,Family::Incompatible);assert_eq!(rows.len(),3);assert!(rows.iter().all(|row|row.message=="/proc/probe sets SpacemanDMM_should_not_override, which cannot be set on global procs"));assert!(observe(source,Family::Disabled).is_empty());assert!(observe(source,Family::Duplicate).is_empty());}
#[test]fn directive_binding_disabled_and_invalid_values_do_not_replace_accepted_first_definition(){let source="/datum/flags/proc/probe()\n    set SpacemanDMM_should_not_sleep = missing_call()\n    set SpacemanDMM_should_not_sleep = 0\n    set SpacemanDMM_should_not_sleep = 1\n    set SpacemanDMM_should_not_sleep = FALSE\n    set SpacemanDMM_should_not_sleep = 1\n    return 0\n";let disabled=observe(source,Family::Disabled);assert_eq!(disabled.len(),2);assert!(disabled.iter().all(|row|row.message=="/datum/flags/proc/probe sets SpacemanDMM_should_not_sleep false, but it cannot be disabled."));let duplicate=observe(source,Family::Duplicate);assert_eq!(duplicate.len(),1);assert_eq!(duplicate[0].message,"/datum/flags/proc/probe sets SpacemanDMM_should_not_sleep twice");assert_eq!(duplicate[0].notes.len(),1);assert_eq!(duplicate[0].notes[0].message,"first definition here");assert_eq!(duplicate[0].notes[0].source.as_ref().unwrap().line,4);}
#[test]fn directive_binding_definition_exclusion_precedes_rhs_and_duplicate_checks(){let source="/datum/base/proc/probe()\n    return 0\n/datum/child\n    parent_type = /datum/base\n/datum/child/probe()\n    set SpacemanDMM_private_proc = 0\n    set SpacemanDMM_private_proc = 1\n    set SpacemanDMM_private_proc = 1\n    set SpacemanDMM_should_call_parent = FALSE\n    return 0\n";assert!(observe(source,Family::Disabled).is_empty());assert!(observe(source,Family::Duplicate).is_empty());assert!(observe(source,Family::Incompatible).is_empty());}
#[test]fn directive_binding_flags_match_exact_pinned_constructors_and_keep_prefix_boundary(){let old=include_str!("checks_directive_binding_original.reference");let names=crate::checks_unknown_linter_setting::KNOWN;for(index,name)in names.iter().enumerate(){let(disable,definition,global)=FLAGS[index];assert!(old.contains(&format!("ProcDirective::new(\"{name}\", {disable}, {definition}, {global})")));}let source="/datum/flags/proc/probe()\n    set SpacemanDMM_should_not_override = TRUE\n    return 0\n    set SpacemanDMM_should_not_override = TRUE\n";assert!(observe(source,Family::Duplicate).is_empty());}

#[test]fn directive_binding_can_disable_accepts_false_and_only_exact_integer_terms_bind(){let source="/datum/flags/proc/probe()\n    set SpacemanDMM_should_call_parent = 0.0\n    set SpacemanDMM_should_call_parent = (0)\n    set SpacemanDMM_should_call_parent = FALSE\n    set SpacemanDMM_should_call_parent = TRUE\n    return 0\n";assert!(observe(source,Family::Disabled).is_empty());let rows=observe(source,Family::Duplicate);assert_eq!(rows.len(),1);assert_eq!(rows[0].notes[0].source.as_ref().unwrap().line,4);}

#[test]fn directive_binding_final_declaration_seeds_duplicate_at_each_original_header(){for(source,first_line)in[("/datum/flags/proc/final/probe()\n    set SpacemanDMM_should_not_override = 1\n    return 0\n",1),("/datum/flags\n    proc/final\n        probe()\n            set SpacemanDMM_should_not_override = 1\n            return 0\n",3)]{let front=build(Path::new("final-proc.dme"),&Source::new(source),&Default::default(),1).unwrap();let member=front.snapshot.tree.member(front.bodies[0].member).unwrap();assert_eq!(member.metadata.flags&dm_ir::PROC_FLAG_FINAL,dm_ir::PROC_FLAG_FINAL);let rows=observe(source,Family::Duplicate);assert_eq!(rows.len(),1);assert_eq!(rows[0].notes[0].source.as_ref().unwrap().line,first_line);assert!(rows[0].message.contains("/datum/flags/proc/probe sets SpacemanDMM_should_not_override twice"));}}
#[test]fn directive_binding_final_global_seed_reports_at_proc_point_without_any_setting(){let source="/proc/final/probe()\n    return 0\n";let rows=observe(source,Family::Incompatible);assert_eq!(rows.len(),1);assert_eq!(rows[0].span.start,source.find('(').unwrap());assert_eq!(rows[0].message,"/proc/probe sets SpacemanDMM_should_not_override, which cannot be set on global procs");assert!(observe(source,Family::Duplicate).is_empty());}
#[test]fn directive_binding_final_seed_is_owner_local_and_repeated_for_actual_override_version(){let source="/datum/base/proc/final/probe()\n    return 0\n/datum/base/probe()\n    set SpacemanDMM_should_not_override = 1\n    return 0\n/datum/child\n    parent_type = /datum/base\n/datum/child/probe()\n    set SpacemanDMM_should_not_override = 1\n    return 0\n";let rows=observe(source,Family::Duplicate);assert_eq!(rows.len(),1);assert_eq!(rows[0].notes[0].source.as_ref().unwrap().line,3);}
#[test]fn directive_binding_macro_override_compares_actual_reported_points_without_body_demand(){let source="#define CHILD_PROC /datum/child/probe()\n/datum/base/proc/probe()\n    return 0\n/datum/child\n    parent_type = /datum/base\nCHILD_PROC\n    set SpacemanDMM_private_proc = FALSE\n    return 0\n";let front=build(Path::new("macro-location.dme"),&Source::new(source),&Default::default(),1).unwrap();let headers=front.callable_header_source().unwrap();assert!(!headers.reported_point(front.bodies[0].member).unwrap().same_reported_point(&headers.reported_point(front.bodies[1].member).unwrap()));assert!(observe(source,Family::Disabled).is_empty());}
#[test]fn directive_binding_colocated_macro_versions_use_location_equality_instead_of_identity(){let source="#define BOTH /datum/base/proc/probe() { set SpacemanDMM_can_be_redefined = 1; return 0; }; /datum/base/probe() { set SpacemanDMM_private_proc = FALSE; return 0; }\nBOTH\n";let front=build(Path::new("colocated.dme"),&Source::new(source),&Default::default(),1).unwrap();assert_eq!(front.bodies.len(),2);let headers=front.callable_header_source().unwrap();let a=front.callable_roster().unwrap().identity_for_member(front.bodies[0].member).unwrap();let b=front.callable_roster().unwrap().identity_for_member(front.bodies[1].member).unwrap();assert_ne!(a,b);assert!(headers.reported_point(front.bodies[0].member).unwrap().same_reported_point(&headers.reported_point(front.bodies[1].member).unwrap()));let rows=observe(source,Family::Disabled);assert_eq!(rows.len(),1);assert!(rows[0].message.contains("SpacemanDMM_private_proc false, but it cannot be disabled."));}

#[test]fn directive_header_source_uses_same_archive_point_survives_frontend_drop_and_refuses_mutated_frame(){let source="/datum/flags/proc/final/probe()\n    return 0\n";let mut front=build(Path::new("header-owner.dme"),&Source::new(source),&Default::default(),1).unwrap();let member=front.bodies[0].member;let expected=front.callable_header_source().unwrap().reported_point(member).unwrap().into_owned();let archive=front.body_archive().unwrap();assert!(front.callable_header_source().unwrap().reported_point(member).unwrap().same_reported_point(&archive.callable_header_source().reported_point(member).unwrap()));front.plan.occurrences[0].semantic_path=std::sync::Arc::from("foreign.dme");assert!(front.callable_header_source().is_err());drop(front);assert_eq!(archive.callable_header_source().reported_point(member).unwrap().into_owned(),expected);}

#[test]fn directive_duplicate_notes_match_original_same_point_and_cross_registered_file_rendering(){
 let colocated="#define BODY /datum/flags/proc/probe() { set SpacemanDMM_should_not_override = 1; set SpacemanDMM_should_not_override = 1; return 0; }\nBODY\n";let rows=observe(colocated,Family::Duplicate);assert_eq!(rows.len(),1);assert_eq!(rows[0].notes[0].legacy_text(),"first definition here");assert!(rows[0].notes[0].source.is_none(),"same-point legacy note is literal text, not a fabricated different coordinate");
 struct Files(std::collections::BTreeMap<std::path::PathBuf,dm_preprocess::AcquiredSource>);
 impl dm_preprocess::SourceProvider for Files{fn read(&self,_:&Path)->Result<String,String>{Err("requires original sources".into())}fn acquired_source(&self,path:&Path)->Result<Option<dm_preprocess::AcquiredSource>,String>{Ok(self.0.get(path).cloned())}fn source_acquisition(&self,path:&Path,text:&dm_preprocess::SourceText)->Option<dm_preprocess::AcquiredSource>{self.0.get(path).filter(|source|source.lease().source_text().same_view(text)).cloned()}}
 let root=std::env::current_dir().unwrap().join("directive-note-files");let project=root.join("project.dme");let files=Files([("project.dme","/datum/flags/proc/probe()\n#include \"first.dm\"\n#include \"second.dm\"\n"),("first.dm","    set SpacemanDMM_should_not_override = 1\n"),("second.dm","    set SpacemanDMM_should_not_override = 1\n    return 0\n")].into_iter().map(|(path,text)|(dm_preprocess::regions::canonical_path(&root.join(path)),dm_preprocess::AcquiredSource::from_original_bytes(text.as_bytes().to_vec(),()))).collect());
 let front=build(&project,&files,&Default::default(),1).unwrap();let arena=BodyArena::new_typed(&front,|_|true);let rows=arena.with_parsed(&front.bodies[0],|body|check(&BodyView::new(&front,body)?,Family::Duplicate,Severity::Warning)).unwrap().unwrap();assert_eq!(rows.len(),1);assert_eq!(rows[0].notes[0].legacy_text(),"first.dm:1:5: first definition here");assert!(rows[0].notes[0].source.is_none(),"cross-file legacy words carry the original registered file key");
}
